parameters.jsCode:
const raw = $input.first().json.text || '{}';
let parsed = {};
try {
  parsed = JSON.parse(raw.replace(/```json|```/g, '').trim());
} catch(e) {
  parsed = { linkedin_post: raw, newsletter_section: '', tweet_thread: '' };
}
const url = $('Extract URL').first().json.url;
return [{ json: { ...parsed, source_url: url, created_at: new Date().toISOString() } }];

